use crate::{Db,Result,err};
use serde_json::{Value,json};
use std::{sync::{Mutex,atomic::{AtomicBool,Ordering}},collections::HashMap,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
use base64::{Engine,engine::general_purpose::URL_SAFE_NO_PAD};
use rand::RngCore;
use sha2::{Sha256,Digest};
use tokio::{net::TcpListener,io::{AsyncReadExt,AsyncWriteExt}};
use url::Url;
pub struct Services{pub db:Db,gate:tokio::sync::Mutex<()>,access:Mutex<HashMap<String,(String,u64)>>,cancel:AtomicBool}
fn now()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()}
fn secret(name:&str)->Result<Option<String>>{
 #[cfg(windows)]{let e=keyring::Entry::new("app.lumi.desktop",name).map_err(|_|"Coffre Windows indisponible")?;match e.get_password(){Ok(v)=>Ok(Some(v)),Err(keyring::Error::NoEntry)=>Ok(None),Err(_)=>Err("Lecture du coffre Windows impossible".into())}}
 #[cfg(not(windows))]{let _=name;Err("Cette version utilise le coffre Windows. Lancez Lumi sous Windows.".into())}
}
fn set_secret(name:&str,value:Option<&str>)->Result<()> {
 #[cfg(windows)]{let e=keyring::Entry::new("app.lumi.desktop",name).map_err(|_|"Coffre Windows indisponible")?;match value{Some(v)=>e.set_password(v).map_err(|_|"Enregistrement dans le coffre Windows impossible".into()),None=>match e.delete_credential(){Ok(())|Err(keyring::Error::NoEntry)=>Ok(()),Err(_)=>Err("Suppression de l’identifiant Windows impossible".into())}}}
 #[cfg(not(windows))]{let _=(name,value);Err("Cette version utilise le coffre Windows.".into())}
}
fn http()->Result<reqwest::Client>{reqwest::Client::builder().timeout(Duration::from_secs(100)).connect_timeout(Duration::from_secs(15)).redirect(reqwest::redirect::Policy::none()).build().map_err(err)}
async fn response(mut r:reqwest::Response)->Result<Value>{let status=r.status();if !status.is_success(){return Err(format!("Le fournisseur a refusé la demande (HTTP {}). {}",status.as_u16(),match status.as_u16(){401|403=>"Vérifiez la clé ou reconnectez le compte avec les permissions requises.",429=>"Quota atteint : attendez avant de réessayer.",404=>"Vérifiez le nom du modèle ou la ressource.",_=>"Vérifiez les identifiants et la configuration."}))}let mut b=Vec::new();while let Some(c)=r.chunk().await.map_err(|_|"Réponse réseau interrompue")?{if b.len()+c.len()>8*1024*1024{return Err("Réponse trop volumineuse".into())}b.extend_from_slice(&c);}serde_json::from_slice(&b).map_err(|_|"Réponse fournisseur invalide".into())}
fn random()->String{let mut b=[0u8;32];rand::rngs::OsRng.fill_bytes(&mut b);URL_SAFE_NO_PAD.encode(b)}
fn challenge(v:&str)->String{URL_SAFE_NO_PAD.encode(Sha256::digest(v.as_bytes()))}
fn validate_provider(p:&str)->Result<()> {if ["google","microsoft"].contains(&p){Ok(())}else{Err("Fournisseur inconnu".into())}}
pub fn validate_api(p:&str,url:&str)->Result<Url>{validate_provider(p)?;let u=Url::parse(url).map_err(|_|"URL invalide")?;let hosts=if p=="google"{vec!["www.googleapis.com","gmail.googleapis.com"]}else{vec!["graph.microsoft.com"]};if u.scheme()!="https"||!hosts.contains(&u.host_str().unwrap_or(""))||!u.username().is_empty()||u.password().is_some()||u.port().is_some(){return Err("Adresse fournisseur interdite".into())}Ok(u)}
fn callback(target:&str,state:&str)->Result<Option<String>>{let u=Url::parse(&format!("http://localhost{target}")).map_err(|_|"Retour invalide")?;if u.path()!="/"{return Err("Chemin invalide".into())}let q:Vec<_>=u.query_pairs().collect();let s:Vec<_>=q.iter().filter(|(k,_)|k=="state").collect();if s.len()!=1||s[0].1.len()!=state.len()||s[0].1.bytes().zip(state.bytes()).fold(0,|a,(b,c)|a|(b^c))!=0{return Err("État OAuth invalide".into())}if q.iter().any(|(k,_)|k=="error"){return Ok(None)}let c:Vec<_>=q.iter().filter(|(k,_)|k=="code").collect();if c.len()!=1||c[0].1.is_empty()||c[0].1.len()>4096{return Err("Code OAuth invalide".into())}Ok(Some(c[0].1.to_string()))}
impl Services {
 pub fn new(db:Db)->Self{Self{db,gate:tokio::sync::Mutex::new(()),access:Mutex::new(HashMap::new()),cancel:AtomicBool::new(false)}}
 fn config(&self)->Result<Value>{Ok(match self.db.get("config/services")?{Value::Null=>json!({}),v=>v})}
 fn write_config(&self,c:Value)->Result<()>{self.db.batch(&json!([{"key":"config/services","value":c}]))}
 pub fn status(&self)->Result<Value>{let c=self.config()?;let mut connections=Vec::new();for p in ["google","microsoft"]{connections.push(json!({"provider":p,"connected":secret(&format!("{p}-refresh"))?.is_some(),"email":c[format!("{p}_email")]}));}Ok(json!({"gemini_configured":secret("gemini")?.is_some(),"model":c["model"].as_str().unwrap_or("gemini-3.8-flash"),"google_client_id":c["google_client_id"],"google_secret_configured":secret("google-client-secret")?.is_some(),"microsoft_client_id":c["microsoft_client_id"],"microsoft_tenant":c["microsoft_tenant"].as_str().unwrap_or("common"),"connections":connections}))}
 pub async fn configure(&self,p:Value)->Result<Value>{let _g=self.gate.try_lock().map_err(|_|"Terminez ou annulez la connexion en cours")?;let mut c=self.config()?;for k in ["model","google_client_id","microsoft_client_id","microsoft_tenant"]{if let Some(s)=p[k].as_str(){let s=s.trim();if s.len()>500||!s.chars().all(|c|c.is_ascii_alphanumeric()||"-._".contains(c)){return Err("Identifiant ou modèle invalide".into())}if k=="model"&&(!s.starts_with("gemini-")||s.len()<8){return Err("Nom de modèle invalide".into())}if (k.ends_with("client_id")||k=="microsoft_tenant")&&c[k].as_str().unwrap_or("")!=s{let provider=if k.starts_with("google"){"google"}else{"microsoft"};set_secret(&format!("{provider}-refresh"),None)?;if provider=="google"{set_secret("google-client-secret",None)?;}self.access.lock().map_err(err)?.remove(provider);c[format!("{provider}_email")]=Value::Null;}c[k]=json!(s);}}
 for (field,name) in [("gemini_key","gemini"),("google_client_secret","google-client-secret")]{if let Some(s)=p[field].as_str(){if !s.trim().is_empty(){if s.len()>2048||s.chars().any(char::is_control){return Err("Clé invalide".into())}set_secret(name,Some(s.trim()))?;}}}if p["remove_gemini"]==true{set_secret("gemini",None)?;}self.write_config(c)?;self.status()}
 pub async fn read_offer(&self,address:&str)->Result<String>{let u=Url::parse(address).map_err(|_|"Lien d’offre invalide")?;if u.scheme()!="https"||!u.username().is_empty()||u.password().is_some()||u.port().is_some()||!["www.linkedin.com","linkedin.com","www.welcometothejungle.com","welcometothejungle.com"].contains(&u.host_str().unwrap_or("")){return Err("Lecture automatique limitée aux liens HTTPS LinkedIn et Welcome to the Jungle. Collez le texte pour un autre site.".into())}let mut r=http()?.get(u).header("User-Agent","LumiDesktop/0.2").send().await.map_err(|_|"Offre inaccessible. Collez son texte ou importez un PDF.")?;if !r.status().is_success(){return Err("Ce site demande une connexion ou bloque la lecture. Collez le texte de l’offre ou importez son PDF.".into())}let mut bytes=Vec::new();while let Some(chunk)=r.chunk().await.map_err(|_|"Lecture interrompue")?{if bytes.len()+chunk.len()>2*1024*1024{return Err("Page trop volumineuse. Importez le PDF de l’offre.".into())}bytes.extend_from_slice(&chunk);}String::from_utf8(bytes).map_err(|_|"Texte illisible. Collez l’offre manuellement.".into())}
 pub async fn generate(&self,body:Value)->Result<Value>{let key=secret("gemini")?.ok_or("Ajoutez votre clé Gemini dans Réglages.")?;if body.to_string().len()>30*1024*1024{return Err("Demande Gemini trop volumineuse".into())}let c=self.config()?;let model=c["model"].as_str().unwrap_or("gemini-3.8-flash");if !model.starts_with("gemini-")||!model.chars().all(|c|c.is_ascii_alphanumeric()||"-.".contains(c)){return Err("Modèle invalide".into())}response(http()?.post(format!("https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent")).header("x-goog-api-key",key).json(&body).send().await.map_err(|_|"Gemini est injoignable. Vérifiez Internet.")?).await}
 fn oauth(&self,p:&str)->Result<(String,String,String,String)>{validate_provider(p)?;let c=self.config()?;let id=c[format!("{p}_client_id")].as_str().unwrap_or("").to_owned();if id.is_empty(){return Err("Renseignez l’identifiant OAuth dans Réglages.".into())}let tenant=c["microsoft_tenant"].as_str().filter(|s|!s.is_empty()).unwrap_or("common");if !tenant.chars().all(|c|c.is_ascii_alphanumeric()||"-.".contains(c)){return Err("Tenant invalide".into())}Ok(if p=="google"{(id,"https://accounts.google.com/o/oauth2/v2/auth".into(),"https://oauth2.googleapis.com/token".into(),"openid email https://www.googleapis.com/auth/gmail.readonly https://www.googleapis.com/auth/calendar.readonly".into())}else{(id,format!("https://login.microsoftonline.com/{tenant}/oauth2/v2.0/authorize"),format!("https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token"),"openid email offline_access User.Read Mail.Read Calendars.Read".into())})}
 async fn token_request(&self,p:&str,mut form:Vec<(&str,String)>)->Result<Value>{let(id,_,url,_)=self.oauth(p)?;form.push(("client_id",id));if p=="google"{if let Some(s)=secret("google-client-secret")?{form.push(("client_secret",s));}}response(http()?.post(url).form(&form).send().await.map_err(|_|"Échange OAuth interrompu")?).await}
 fn cache_token(&self,p:&str,t:&Value)->Result<String>{let token=t["access_token"].as_str().ok_or("Autorisation incomplète")?.to_owned();if let Some(r)=t["refresh_token"].as_str(){set_secret(&format!("{p}-refresh"),Some(r))?;}if secret(&format!("{p}-refresh"))?.is_none(){return Err("Accès hors ligne manquant. Reconnectez le compte et acceptez les permissions.".into())}self.access.lock().map_err(err)?.insert(p.into(),(token.clone(),now()+t["expires_in"].as_u64().unwrap_or(3600)));Ok(token)}
 async fn access(&self,p:&str)->Result<String>{if let Some((t,expiry))=self.access.lock().map_err(err)?.get(p){if *expiry>now()+60{return Ok(t.clone())}}let r=secret(&format!("{p}-refresh"))?.ok_or("Connectez ce compte dans Réglages")?;let t=self.token_request(p,vec![("grant_type","refresh_token".into()),("refresh_token",r)]).await?;self.cache_token(p,&t)}
 pub async fn get(&self,p:&str,url:&str)->Result<Value>{let url=validate_api(p,url)?;let _g=self.gate.lock().await;let token=self.access(p).await?;let mut req=http()?.get(url).bearer_auth(token);if p=="microsoft"{req=req.header("Prefer","outlook.timezone=\"UTC\", IdType=\"ImmutableId\"");}response(req.send().await.map_err(|_|"Messagerie ou calendrier injoignable")?).await}
 pub fn cancel(&self){self.cancel.store(true,Ordering::SeqCst);}
 pub async fn disconnect(&self,p:&str)->Result<Value>{validate_provider(p)?;let _g=self.gate.try_lock().map_err(|_|"Une opération est en cours")?;set_secret(&format!("{p}-refresh"),None)?;self.access.lock().map_err(err)?.remove(p);let mut c=self.config()?;c[format!("{p}_email")]=Value::Null;self.write_config(c)?;self.status()}
 pub async fn connect<F:Fn(String)->Result<()>>(&self,p:&str,open:F)->Result<Value>{let _g=self.gate.try_lock().map_err(|_|"Une connexion est déjà en cours")?;let(id,auth,_,scope)=self.oauth(p)?;let listener=TcpListener::bind("127.0.0.1:0").await.map_err(|_|"Impossible d’ouvrir le retour OAuth local")?;let redirect=format!("http://{}:{}/",if p=="google"{"127.0.0.1"}else{"localhost"},listener.local_addr().map_err(err)?.port());let state=random();let verifier=random();let ch=challenge(&verifier);let mut url=Url::parse(&auth).map_err(err)?;url.query_pairs_mut().extend_pairs([("client_id",id.as_str()),("scope",scope.as_str()),("response_type","code"),("redirect_uri",redirect.as_str()),("state",state.as_str()),("code_challenge",ch.as_str()),("code_challenge_method","S256"),("prompt",if p=="google"{"consent"}else{"select_account"})]);if p=="google"{url.query_pairs_mut().append_pair("access_type","offline");}self.cancel.store(false,Ordering::SeqCst);open(url.to_string())?;let start=Instant::now();
 let code=loop{if self.cancel.load(Ordering::SeqCst){return Err("Connexion annulée".into())}if start.elapsed()>Duration::from_secs(300){return Err("Connexion expirée. Réessayez depuis Lumi.".into())}let(mut socket,_)=match tokio::time::timeout(Duration::from_secs(1),listener.accept()).await{Ok(Ok(x))=>x,Ok(Err(_))=>return Err("Retour OAuth interrompu".into()),Err(_)=>continue};let mut bytes=Vec::new();let result=tokio::time::timeout(Duration::from_secs(3),async{loop{let mut b=[0u8;1024];let n=socket.read(&mut b).await?;if n==0{break}bytes.extend_from_slice(&b[..n]);if bytes.len()>8192||bytes.windows(4).any(|x|x==b"\r\n\r\n"){break}}Ok::<(),std::io::Error>(())}).await;let text=String::from_utf8_lossy(&bytes);let line:Vec<_>=text.lines().next().unwrap_or("").split_whitespace().collect();let outcome=if matches!(result,Ok(Ok(())))&&bytes.len()<=8192&&line.len()==3&&line[0]=="GET"{callback(line[1],&state)}else{Err("Requête invalide".into())};let valid=outcome.is_ok();let html=if valid{"<!doctype html><meta charset=utf-8><title>Lumi</title><h1>Retournez dans Lumi.</h1><p>La connexion se termine dans votre application. Vous pouvez fermer cet onglet.</p>"}else{"Retour de connexion invalide."};let reply=format!("HTTP/1.1 {}\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nCache-Control: no-store\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: default-src 'none'; frame-ancestors 'none'\r\nConnection: close\r\n\r\n{}",if valid{"200 OK"}else{"400 Bad Request"},html.len(),html);let _=socket.write_all(reply.as_bytes()).await;let _=socket.shutdown().await;if let Ok(code)=outcome{break code.ok_or("Autorisation refusée dans le navigateur")?;}};
 let token=self.token_request(p,vec![("grant_type","authorization_code".into()),("code",code),("redirect_uri",redirect),("code_verifier",verifier)]).await?;let access=token["access_token"].as_str().ok_or("Autorisation incomplète")?;let endpoint=if p=="google"{"https://www.googleapis.com/oauth2/v3/userinfo"}else{"https://graph.microsoft.com/v1.0/me?$select=mail,userPrincipalName"};let identity=response(http()?.get(endpoint).bearer_auth(access).send().await.map_err(|_|"Impossible de vérifier le compte")?).await?;self.cache_token(p,&token)?;let mut c=self.config()?;c[format!("{p}_email")]=json!(identity["email"].as_str().or(identity["mail"].as_str()).or(identity["userPrincipalName"].as_str()).unwrap_or("Compte connecté"));self.write_config(c)?;self.status()}
}
#[cfg(test)]mod tests{use super::*;
#[test]fn pkce_vector(){assert_eq!(challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"),"E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM");assert_ne!(random(),random());}
#[test]fn state_and_callback(){assert_eq!(callback("/?state=a&code=b","a").unwrap(),Some("b".into()));for t in ["/?state=c&code=b","/?state=a&state=a&code=b","/other?state=a&code=b","/?state=a&code=b&code=c"]{assert!(callback(t,"a").is_err())}assert_eq!(callback("/?state=a&error=denied","a").unwrap(),None);}
#[test]fn tokens_never_go_to_unapproved_hosts(){for u in ["http://graph.microsoft.com","https://graph.microsoft.com.evil.test","https://user@graph.microsoft.com","https://graph.microsoft.com:444","file:///tmp"]{assert!(validate_api("microsoft",u).is_err())}assert!(validate_api("google","https://graph.microsoft.com").is_err());assert!(validate_api("microsoft","https://graph.microsoft.com/v1.0/me").is_ok());}
#[tokio::test]async fn loopback_rejects_wrong_state_then_accepts_denial(){
 let path=std::env::temp_dir().join(format!("lumi-test-{}.sqlite3",random()));let svc=Services::new(Db::open(&path).unwrap());svc.write_config(json!({"microsoft_client_id":"test-client"})).unwrap();
 let result=svc.connect("microsoft",|address|{let u=Url::parse(&address).unwrap();let q:HashMap<_,_>=u.query_pairs().into_owned().collect();assert_eq!(q["code_challenge_method"],"S256");let redirect=q["redirect_uri"].clone();let state=q["state"].clone();tokio::spawn(async move{let client=reqwest::Client::new();let r=client.get(format!("{redirect}?state=wrong&code=fake")).send().await.unwrap();assert_eq!(r.status().as_u16(),400);let r=client.get(format!("{redirect}?state={state}&error=access_denied")).send().await.unwrap();assert_eq!(r.status().as_u16(),200);});Ok(())}).await;
 assert!(result.unwrap_err().contains("refusée"));drop(svc);let _=std::fs::remove_file(path);
}
#[tokio::test]async fn loopback_can_be_cancelled(){
 let path=std::env::temp_dir().join(format!("lumi-test-{}.sqlite3",random()));let svc=Services::new(Db::open(&path).unwrap());svc.write_config(json!({"google_client_id":"test-client"})).unwrap();let result=svc.connect("google",|_|{svc.cancel();Ok(())}).await;assert!(result.unwrap_err().contains("annulée"));drop(svc);let _=std::fs::remove_file(path);
}

}
